    @SuppressWarnings("unchecked")
    private static final java.lang.ref.SoftReference<java.awt.image.BufferedImage>[] CACHE = new java.lang.ref.SoftReference[DATA.length];

    private static final java.awt.image.BufferedImage[] HOLD = new java.awt.image.BufferedImage[DATA.length];

    static void preload() {
        Thread t = new Thread(() -> { for (int i = 0; i < DATA.length; i++) get(i); }, "art-preload");
        t.setDaemon(true);
        t.setPriority(Thread.NORM_PRIORITY - 1);
        t.start();
    }

    static synchronized java.awt.image.BufferedImage get(int i) {
        if (HOLD[i] != null) return HOLD[i];
        java.awt.image.BufferedImage im = CACHE[i] == null ? null : CACHE[i].get();
        if (im == null) {
            try {
                byte[] raw = java.util.Base64.getDecoder().decode(String.join("", DATA[i]));
                im = javax.imageio.ImageIO.read(new ByteArrayInputStream(raw));
            } catch (Exception e) {
                im = new java.awt.image.BufferedImage(2, 2, java.awt.image.BufferedImage.TYPE_INT_RGB);
            }
            CACHE[i] = new java.lang.ref.SoftReference<>(im);
        }
        HOLD[i] = im;
        return im;
    }

    static void cover(Graphics2D g, java.awt.image.BufferedImage im, int x, int y, int w, int h, double focusY) {
        double sc = Math.max((double) w / im.getWidth(), (double) h / im.getHeight());
        int dw = (int) Math.ceil(im.getWidth() * sc), dh = (int) Math.ceil(im.getHeight() * sc);
        Shape old = g.getClip();
        g.clipRect(x, y, w, h);
        g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BICUBIC);
        g.drawImage(im, x + (w - dw) / 2, y - (int) ((dh - h) * focusY), dw, dh, null);
        g.setClip(old);
    }

    private static final java.util.LinkedHashMap<java.util.List<Object>, java.lang.ref.SoftReference<java.awt.image.BufferedImage>> COVERS =
            new java.util.LinkedHashMap<>(8, 0.75f, true) {
                @Override protected boolean removeEldestEntry(Map.Entry<java.util.List<Object>, java.lang.ref.SoftReference<java.awt.image.BufferedImage>> e) { return size() > 6; }
            };

    static void coverCached(Graphics2D g, java.awt.image.BufferedImage im, int x, int y, int w, int h, double focusY) {
        if (w <= 0 || h <= 0) return;
        java.util.List<Object> key = java.util.List.of(System.identityHashCode(im), w, h, focusY);
        java.lang.ref.SoftReference<java.awt.image.BufferedImage> ref = COVERS.get(key);
        java.awt.image.BufferedImage out = ref == null ? null : ref.get();
        if (out == null) {
            out = new java.awt.image.BufferedImage(w, h, java.awt.image.BufferedImage.TYPE_INT_RGB);
            Graphics2D og = out.createGraphics();
            cover(og, im, 0, 0, w, h, focusY);
            og.dispose();
            COVERS.put(key, new java.lang.ref.SoftReference<>(out));
        }
        g.drawImage(out, x, y, null);
    }
